// === Configuración de sensores simulados ===
// Editar este arreglo con los datos reales obtenidos desde el panel
// Admin → Sensores → "Ver token". sensorId debe coincidir con el ID
// devuelto en la creación del sensor.
//
// También se pueden definir vía variables de entorno:
//   SENSORES_JSON='[{"sensorId":1,"token":"<jwt>","tipo":"clima"}, ...]'

let sensores = [];
if ($env.SENSORES_JSON) {
  try { sensores = JSON.parse($env.SENSORES_JSON); }
  catch (e) { throw new Error('SENSORES_JSON inválido: ' + e.message); }
} else {
  sensores = [
    // { sensorId: 1, token: 'eyJhbGciOiJI...', tipo: 'clima' },
    // { sensorId: 2, token: 'eyJhbGciOiJI...', tipo: 'suelo' },
    // { sensorId: 3, token: 'eyJhbGciOiJI...', tipo: 'riego' },
  ];
}

if (!Array.isArray(sensores) || sensores.length === 0) {
  return [{ json: { _skip: true, reason: 'No hay sensores configurados. Edite el nodo "Generar lecturas" o defina SENSORES_JSON.' } }];
}

const r = (min, max) => Math.round((min + Math.random() * (max - min)) * 100) / 100;

const tipos = {
  clima: () => ({
    tempMax: r(20, 34),
    tempMin: r(8, 18),
    precipitacion: Math.random() > 0.7 ? r(0.5, 25) : 0,
    humedadRelativa: r(40, 90),
    radiacionSolar: r(15, 28),
    velocidadViento: r(3, 22),
  }),
  suelo: () => ({
    humedad: r(18, 55),
    ph: r(5.5, 7.8),
    nitrogenoDisponible: r(18, 50),
    fosforoDisponible: r(10, 35),
    conductividadElectrica: r(0.8, 2.5),
  }),
  riego: () => ({
    tipoRiego: ['Goteo', 'Aspersión', 'Pivote Central'][Math.floor(Math.random() * 3)],
    volumenAplicadoL: Math.round(r(800, 4500)),
    duracionHoras: r(0.5, 4),
    presionBar: r(1.0, 3.5),
  }),
};

const out = [];
for (const s of sensores) {
  const gen = tipos[s.tipo];
  if (!gen) continue;
  out.push({ json: { sensorId: s.sensorId, token: s.token, data: { fecha: new Date().toISOString().split('T')[0], ...gen() } } });
}

return out;
